function initLogoutForm() {
  var appElement = document.getElementById('logout-app');
  if (!appElement) {
    console.error('Container for form is not found');
    return;
  }
  var app = createApp({
    components: {
      LogoutForm: LogoutForm
    },
    template: '<LogoutForm/>'
  });
  app.mount(appElement);
}
